'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var bench = require( '@stdlib/bench' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var Int32Array = require( '@stdlib/array/int32' );
var uniform = require( '@stdlib/random/array/uniform' );
var randi = require( '@stdlib/random/base/randi' );
var pow = require( '@stdlib/math/base/special/pow' );
var floor = require( '@stdlib/math/base/special/floor' );
var isColumnMajor = require( '@stdlib/ndarray/base/assert/is-column-major-string' );
var tryRequire = require( '@stdlib/utils/try-require' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;


// VARIABLES //

var dcomputeInertia = tryRequire( resolve( __dirname, './../lib/ndarray.native.js' ) );
var opts = {
	'skip': ( dcomputeInertia instanceof Error )
};
var LAYOUTS = [
	'row-major',
	'column-major'
];
var K = 4; // number of centroids
var options = {
	'dtype': 'float64'
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {string} order - storage layout
* @param {PositiveInteger} N - number of data points and features along each dimension
* @returns {Function} benchmark function
*/
function createBenchmark( order, N ) {
	var labels;
	var sx1;
	var sx2;
	var sc1;
	var sc2;
	var X;
	var C;
	var i;

	X = uniform( N*N, -10000.0, 10000.0, options );
	C = uniform( K*N, -10000.0, 10000.0, options );
	labels = new Int32Array( N );
	for ( i = 0; i < N; i++ ) {
		labels[ i ] = randi() % K;
	}

	if ( isColumnMajor( order ) ) {
		sx1 = 1;
		sx2 = N;
		sc1 = 1;
		sc2 = K;
	} else { // order === 'row-major'
		sx1 = N;
		sx2 = 1;
		sc1 = N;
		sc2 = 1;
	}
	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var z;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			z = dcomputeInertia( N, N, K, 'sqeuclidean', X, sx1, sx2, 0, C, sc1, sc2, 0, labels, 1, 0 );
			if ( isnan( z ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnan( z ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var min;
	var max;
	var ord;
	var N;
	var f;
	var i;
	var k;

	min = 1; // 10^min
	max = 6; // 10^max

	for ( k = 0; k < LAYOUTS.length; k++ ) {
		ord = LAYOUTS[ k ];
		for ( i = min; i <= max; i++ ) {
			N = floor( pow( pow( 10, i ), 1.0/2.0 ) );
			f = createBenchmark( ord, N );
			bench( format( '%s::native:ndarray:order=%s,size=%d', pkg, ord, N*N ), opts, f );
		}
	}
}

main();
